document.addEventListener("DOMContentLoaded", async function () {
  const video = document.getElementById("registration-video");
  const canvas = document.getElementById("registration-canvas");
  const photo = document.getElementById("registration-photo");
  const capture = document.getElementById("registration-capture");
  const status = document.getElementById("registration-status");
  const resetBtn = document.getElementById("registration-reset");

  const DESCRIPTORS_TO_COLLECT = 12;
  const FRAME_DELAY = 120;

  let collectedDescriptors = [];
  let capturedImage = null;
  let isConfirmMode = false;

  // =============================
  // LOAD MODELS
  // =============================
  const modelUrl = "/assets/mapl_customization/models";
  await Promise.all([
    faceapi.nets.tinyFaceDetector.loadFromUri(modelUrl),
    faceapi.nets.faceLandmark68Net.loadFromUri(modelUrl),
    faceapi.nets.faceRecognitionNet.loadFromUri(modelUrl),
  ]);

  // =============================
  // CAMERA
  // =============================
  const stream = await navigator.mediaDevices.getUserMedia({
    video: { facingMode: "user" },
  });
  video.srcObject = stream;
  await new Promise((r) => (video.onloadedmetadata = r));

  capture.disabled = false;
  status.innerText = "Keep your face steady and click Capture";

  resetBtn.onclick = () => location.reload();

  // =============================
  // CAPTURE BUTTON
  // =============================
  capture.addEventListener("click", async () => {
    if (!isConfirmMode) {
      await collectDescriptors();
      return;
    }

    // =============================
    // CONFIRM & SAVE
    // =============================
    const employee = prompt("Enter Employee ID:");
    const registration_code = prompt("Enter Registration Code:");

    if (!employee || !registration_code) {
      status.innerText = "Registration cancelled.";
      return;
    }

    status.innerText = "Saving face data...";

    frappe.call({
      method:
        "mapl_customization.customizations_for_mapl.employee_gps_attendance.update_face_descriptor",
      args: {
        employee: employee,
        registration_code: registration_code,
        descriptors: collectedDescriptors, // 🔥 MULTIPLE
        image_data: capturedImage,
      },
      callback: () => {
        status.innerText = "Face registered successfully!";
        capture.disabled = true;
        video.srcObject.getTracks().forEach(t => t.stop());
      },
      error: () => {
        status.innerText = "Error saving face data";
      },
    });
  });

  // =============================
  // MULTI-DESCRIPTOR COLLECTION
  // =============================
  async function collectDescriptors() {
    collectedDescriptors = [];
    status.innerText = "Capturing face samples...";

    const ctx = canvas.getContext("2d");
    canvas.width = video.videoWidth;
    canvas.height = video.videoHeight;

    // Capture reference image
    ctx.drawImage(video, 0, 0, canvas.width, canvas.height);
    capturedImage = canvas.toDataURL("image/png");
    photo.src = capturedImage;

    for (let i = 0; i < DESCRIPTORS_TO_COLLECT; i++) {
      ctx.drawImage(video, 0, 0, canvas.width, canvas.height);

      const detection = await faceapi
        .detectSingleFace(
          canvas,
          new faceapi.TinyFaceDetectorOptions({
            inputSize: 320,
            scoreThreshold: 0.6,
          })
        )
        .withFaceLandmarks()
        .withFaceDescriptor();

      if (detection) {
        collectedDescriptors.push(Array.from(detection.descriptor));
        status.innerText = `Captured ${collectedDescriptors.length}/${DESCRIPTORS_TO_COLLECT}`;
      }

      await new Promise((r) => setTimeout(r, FRAME_DELAY));
    }

    if (collectedDescriptors.length < 6) {
      status.innerText = "Face unstable. Try again.";
      collectedDescriptors = [];
      return;
    }

    // Preview
    video.style.display = "none";
    photo.style.display = "block";
    capture.innerText = "Confirm & Register";
    isConfirmMode = true;
    status.innerText = "Confirm photo and register";
  }
});

// Daily Attendance Script
  document.addEventListener("DOMContentLoaded", async () => {
    const video = document.getElementById("attendance-video");
    const canvas = document.getElementById("attendance-canvas");
    const photo = document.getElementById("attendance-photo");
    const status = document.getElementById("attendance-status");
    const capture = document.getElementById("attendance-capture");
    const post = document.getElementById("attendance-post");
    
    // Initially disabled
    post.disabled = true;

    capture.disabled = true;

    status.innerText = "Loading employee descriptors...";

    // Load registered employee descriptors from ERPNext
    window.labeledDescriptors = [];
    await frappe.call({
      method: "mapl_customization.customizations_for_mapl.employee_gps_attendance.get_employee_descriptors",
      async: false,
      callback: function(r){
        if(r.message){
          console.log(r.message);
            window.labeledDescriptors = r.message.map(e => {
              let raw = typeof e.descriptor === "string"
                ? JSON.parse(e.descriptor)
                : e.descriptor;
            
              // 🔁 BACKWARD COMPATIBILITY
              // Old data: [128]
              // New data: [[128], [128], ...]
              if (raw.length === 128) {
                raw = [raw];
              }
            
              const floatDescriptors = raw.map(d =>
                new Float32Array(d.map(x => parseFloat(x)))
              );
            
              return new faceapi.LabeledFaceDescriptors(
                e.employee_id + "|" + e.employee_name,
                floatDescriptors
              );
            });
        }
      }
    });
    
    // Example usage:
    if (!validateLabeledDescriptors(window.labeledDescriptors)) {
        status.innerText = "Error: labeled descriptors are invalid.";
        return;
    }

    status.innerText = "Loading face models...";

    // Load face-api.js models
    const modelUrl = '/assets/mapl_customization/models';
    await Promise.all([
      faceapi.nets.tinyFaceDetector.loadFromUri(modelUrl),
      faceapi.nets.faceLandmark68Net.loadFromUri(modelUrl),
      faceapi.nets.faceRecognitionNet.loadFromUri(modelUrl)
    ]);

    const faceMatcher = new faceapi.FaceMatcher(window.labeledDescriptors, 0.40); //Lower Value is Strict on Matching Faces

    status.innerText = "Starting camera...";

    // Start video camera
    try {
      const stream = await navigator.mediaDevices.getUserMedia({ video: { facingMode: "user" } });
      video.srcObject = stream;
      await new Promise(resolve => video.onloadedmetadata = resolve);
    } catch(err) {
      status.innerText = "Camera not permitted: " + err.message;
      return;
    }

    status.innerText = "Ready. Click 'Capture Photo'.";

    capture.disabled = false;

    capture.addEventListener("click", async () => {
      //status.innerText = "Detecting face...";

      // Capture current frame to canvas for image
      const ctx = canvas.getContext("2d");
      canvas.width = video.videoWidth;
      canvas.height = video.videoHeight;
      ctx.drawImage(video, 0, 0, canvas.width, canvas.height);
      photo.src = canvas.toDataURL("image/png");

      capture.disabled = true;
      status.innerText = "Trying to Capture GPS...";

      // Capture GPS
      if(!navigator.geolocation){
        status.innerText = "GPS not supported";
        capture.disabled = false;
        return;
      }
      
      let pos;
      try {
        pos = await getLocationOnce(); //await getPosition();
      } catch (err) {
       status.innerText = "GPS error: " + err.message;
       capture.disabled = false;
       return;
      }

        status.innerText = "Getting Coordinates...";
        let latitude = pos.coords.latitude;
        let longitude = pos.coords.longitude;
        status.innerText = "Got Coordinates..."+pos.coords.latitude;

        // Face detection directly from video
        let detection = null;        
        const options = new faceapi.TinyFaceDetectorOptions({inputSize: 320,scoreThreshold: 0.4});
        try {
            detection = await faceapi
            .detectSingleFace(canvas, options)
            .withFaceLandmarks()
            .withFaceDescriptor();
            status.innerText = "Detecting Face ..."
            if(!detection) {
                status.innerText = "Face not detected. Ensure your face is fully visible.";
                capture.disabled = false;
                return;
            }
        } catch(err) {
            status.innerText = "Face detection error: " + err.message;
            capture.disabled = false;
            console.error(err);
            return;
        }

        // Example usage when detecting face:
        if (!validateDetectionDescriptor(detection.descriptor)) {
            status.innerText = "Error: invalid detection descriptor.";
            return;
        }

        status.innerText = "Face Matcher";
        // Safe call to findBestMatch
        let bestMatch;
        try {
            bestMatch = faceMatcher.findBestMatch(detection.descriptor);
            console.log("Best match:", bestMatch);
            status.innerText = "Face recognized: "+bestMatch.label;//+"  Coordinates:"+latitude.toString()+","+longitude.toString();
              if(bestMatch.label !== "unknown"){
                const [employeeId, employeeName] = bestMatch.label.split("|");
                
                drawAttendanceOverlay(canvas, {
                  name: employeeName,
                  employeeId: employeeId,
                  latitude: latitude,
                  longitude: longitude,
                  timestamp: new Date()
                });
                // Show final image preview to user
                photo.src = canvas.toDataURL("image/png");
                photo.style.display = "block";
                video.style.display = "none";
                
                // Enable the POST button only after successful recognition
                post.disabled = false;
                // Store latest info for POST
                post.latestAttendance = {
                  employee: employeeId,   //bestMatch.label.split("|")[0],
                  name: bestMatch.label.split("|")[1],
                  //image_data: canvas.toDataURL("image/png"),
                  //image_data: getCompressedImageFromCanvas(canvas, 400, 0.65), //PNG
                  //image_data: await compressToTargetSize(canvas, 5, 320, "image/jpeg"), //Jpeg
                  image_data: await compressToTargetSize(canvas, 5), //webP
                  attendance_latitude: latitude,
                  attendance_longitude: longitude
                };
              } else {
                status.innerText = "Face not recognized.";
                capture.disabled = false;
                return;
            }            
        } catch(err) {
            console.error("FaceMatcher failed:", err);
            status.innerText = "FaceMatcher failed: " + err.message;
            capture.disabled = false;
        }
    });
    
post.addEventListener("click", async () => {
  if (!post.latestAttendance) {
    status.innerText = "No attendance to post.";
    return;
  }

  status.innerText = "Posting attendance...";

  try {
// Save descriptor to ERPNext
    frappe.call({
      method: "mapl_customization.customizations_for_mapl.employee_gps_attendance.post_attendance",
      args: {
        employee: post.latestAttendance.employee,
        latitude: post.latestAttendance.attendance_latitude,
        longitude: post.latestAttendance.attendance_longitude,
        image_data: post.latestAttendance.image_data
      },
      callback: function (r) {
        status.innerText = "Successfully Marked!";
      },
      error: function (err) {
        console.error(err);
        status.innerText = "Error: " + err.message;
      }
    });
  } catch(err) {
    console.error(err);
    status.innerText = "Error posting attendance: " + err.message;
  }
});

  });



function validateLabeledDescriptors(labeledDescriptors) {
  if (!Array.isArray(labeledDescriptors)) {
    console.error("labeledDescriptors is not an array");
    return false;
  }

  for (const ld of labeledDescriptors) {
    if (typeof ld.label !== "string") {
      console.error("Invalid label:", ld);
      return false;
    }
    if (!Array.isArray(ld.descriptors) || ld.descriptors.length === 0) {
      console.error("Descriptors array missing for label:", ld.label);
      return false;
    }

    for (const d of ld.descriptors) {
      if (!(d instanceof Float32Array)) {
        console.error("Descriptor is not Float32Array for label:", ld.label);
        return false;
      }
      if (d.length !== 128) {
        console.error("Descriptor length != 128 for label:", ld.label);
        return false;
      }
      if (Array.from(d).some(isNaN)) {
        console.error("Descriptor contains NaN for label:", ld.label);
        return false;
      }
    }
  }

  console.log("All labeled descriptors are valid.");
  return true;
}

// Validate detection descriptor
function validateDetectionDescriptor(descriptor) {
  if (!(descriptor instanceof Float32Array)) {
    console.error("Detection descriptor is not Float32Array", descriptor);
    return false;
  }
  if (descriptor.length !== 128) {
    console.error("Detection descriptor length != 128", descriptor);
    return false;
  }
  if (Array.from(descriptor).some(isNaN)) {
    console.error("Detection descriptor contains NaN", descriptor);
    return false;
  }
  return true;
}

function getPosition() {
  return new Promise((resolve, reject) => {
    navigator.geolocation.getCurrentPosition(
      resolve,
      reject,
      { enableHighAccuracy: true, timeout: 10000, maximumAge: 0 }
    );
  });
}

function getCompressedImageFromCanvas(sourceCanvas, maxWidth = 400, quality = 0.7) {
  const ratio = sourceCanvas.height / sourceCanvas.width;
  const width = Math.min(sourceCanvas.width, maxWidth);
  const height = width * ratio;

  const resizedCanvas = document.createElement("canvas");
  resizedCanvas.width = width;
  resizedCanvas.height = height;

  const ctx = resizedCanvas.getContext("2d");
  ctx.drawImage(sourceCanvas, 0, 0, width, height);

  // JPEG is MUCH smaller than PNG
  return resizedCanvas.toDataURL("image/jpeg", quality);
}

async function compressToTargetSize(
  sourceCanvas,
  targetKB = 5,
  maxWidth = 320,
  format = "image/webp" // fallback to jpeg if needed
) {
  const ratio = sourceCanvas.height / sourceCanvas.width;
  const width = Math.min(sourceCanvas.width, maxWidth);
  const height = Math.round(width * ratio);

  const canvas = document.createElement("canvas");
  canvas.width = width;
  canvas.height = height;

  const ctx = canvas.getContext("2d");
  ctx.drawImage(sourceCanvas, 0, 0, width, height);

  let quality = 0.9;
  let dataUrl = "";
  let sizeKB = Infinity;

  while (quality > 0.1) {
    dataUrl = canvas.toDataURL(format, quality);
    sizeKB = Math.round((dataUrl.length * 3) / 4 / 1024);

    if (sizeKB <= targetKB) break;
    quality -= 0.05;
  }

  console.log(`Final image size: ${sizeKB} KB @ quality ${quality}`);
  return dataUrl;
}

function drawAttendanceOverlay(canvas, {
      name,
      employeeId,
      latitude,
      longitude,
      timestamp = new Date()
    }) {
      const ctx = canvas.getContext("2d");
    
      const padding = 12;
      const lineHeight = 18;
    
      const textLines = [
        `Name: ${name}`,
        `Employee ID: ${employeeId}`,
        `Date: ${timestamp.toLocaleDateString()}`,
        `Time: ${timestamp.toLocaleTimeString()}`,
        `Lat: ${latitude.toFixed(6)}`,
        `Lng: ${longitude.toFixed(6)}`
      ];
    
      ctx.font = "14px Arial";
      ctx.textBaseline = "top";
    
      // Calculate background box height
      const boxHeight = textLines.length * lineHeight + padding * 2;
      const boxWidth = canvas.width;
    
      // Semi-transparent background
      ctx.fillStyle = "rgba(0, 0, 0, 0.6)";
      ctx.fillRect(0, canvas.height - boxHeight, boxWidth, boxHeight);
    
      // Text color
      ctx.fillStyle = "#ffffff";
    
      textLines.forEach((line, index) => {
        ctx.fillText(
          line,
          padding,
          canvas.height - boxHeight + padding + index * lineHeight
        );
      });
}


const getLocationOnce = (() => {
  let cachedLocation = null;
  let cachedAt = 0;
  let locationPromise = null;
  let resetTimer = null;

  const CACHE_TTL = 2 * 60 * 1000;

  function reset() {
    cachedLocation = null;
    cachedAt = 0;
    locationPromise = null;
    if (resetTimer) clearTimeout(resetTimer);
    resetTimer = null;
  }

  function scheduleReset() {
    if (resetTimer) clearTimeout(resetTimer);
    resetTimer = setTimeout(reset, CACHE_TTL);
  }

  function get() {
    const now = Date.now();

    if (cachedLocation && now - cachedAt < CACHE_TTL) {
      return Promise.resolve(cachedLocation);
    }

    if (locationPromise) return locationPromise;

    locationPromise = new Promise((resolve, reject) => {
      navigator.geolocation.getCurrentPosition(
        pos => {
          cachedLocation = pos;
          cachedAt = Date.now();
          locationPromise = null;
          scheduleReset();
          resolve(pos);
        },
        err => {
          locationPromise = null;
          reject(err);
        },
        { enableHighAccuracy: true, timeout: 10000, maximumAge: 30000 }
      );
    });

    return locationPromise;
  }

  get.reset = reset;
  return get;
})();
